// Test stackalloc with native-sized integers (nint / nuint)
unsafe
{
    Span<nint> signedSpan = stackalloc nint[4];
    for (int i = 0; i < signedSpan.Length; i++)
        signedSpan[i] = i * 10;

    Span<nuint> unsignedSpan = stackalloc nuint[4];
    for (int i = 0; i < unsignedSpan.Length; i++)
        unsignedSpan[i] = (nuint)(i * 20);

    Console.WriteLine($"nint span length: {signedSpan.Length}, values: {signedSpan[0]}, {signedSpan[1]}, {signedSpan[2]}, {signedSpan[3]}");
    Console.WriteLine($"nuint span length: {unsignedSpan.Length}, values: {unsignedSpan[0]}, {unsignedSpan[1]}, {unsignedSpan[2]}, {unsignedSpan[3]}");
    Console.WriteLine($"sizeof(nint) = {sizeof(nint)} bytes (native pointer size)");
}

